-- Fișierul se rulează automat de database.py, o singură dată, când nu există books.db.

-- 1. Tabelul de cărți
create table books (
  id          integer primary key autoincrement,
  title       text not null,
  author      text not null,
  category    text not null,
  description text not null
);

